using System;using System.Linq;using System.Collections.Generic;using System.Xml;
namespace BeamScheduleFormatter {
static class PowIssueOutput {
 internal static WorksExcelTable Table(IEnumerable<string> input){var issues=input.Distinct().ToList();var rows=issues.Count==0?new List<object[]>{new object[]{"OK","","No input issues","All available quantities included"}}:issues.Select((issue,n)=>new object[]{"PARTIAL",n+1,issue.Length>32000?issue.Substring(0,32000)+"… (full input retained in POW)":issue,"Invalid entry omitted; original input retained in POW"}).ToList();return new WorksExcelTable("POW Input Issues",new[]{"Output status","No.","Input issue","Treatment"},rows);}
 internal static void ExcludeTargets(BackupWritePlan plan,IEnumerable<string> slots){var blocked=new HashSet<string>(slots,StringComparer.Ordinal);var keys=new HashSet<string>(plan.Routes.Where(r=>blocked.Contains(r.Value.SlotId)).Select(r=>r.Key),StringComparer.Ordinal);plan.Demands=plan.Demands.Where(d=>!keys.Contains(d.Key)).ToList();foreach(string key in keys)plan.Routes.Remove(key);}
 internal static void Write(XmlElement root,IEnumerable<string> issues){var section=root.OwnerDocument.CreateElement("InputIssues");root.AppendChild(section);foreach(string issue in issues.Distinct()){var entry=root.OwnerDocument.CreateElement("Issue");entry.InnerText=issue;section.AppendChild(entry);}section.SetAttribute("output",section.HasChildNodes?"Partial":"Complete");}
}
sealed partial class ExcelLiveLink {
 string lastIssueText;
 internal void UpdateInputIssues(List<string> issues,bool force=false){string stamp=string.Join("\n",issues.Distinct());if(!force&&stamp==lastIssueText)return;dynamic active=null;try{active=app.ActiveSheet;}catch{}var table=PowIssueOutput.Table(issues);bool events=Convert.ToBoolean(app.EnableEvents),updates=Convert.ToBoolean(app.ScreenUpdating);try{app.EnableEvents=false;app.ScreenUpdating=false;string name=table.Name;dynamic sheet=FindEstimateSheet(name);int suffix=2;while(sheet!=null&&Convert.ToString(sheet.Range["AA1"].Value2)!="DTCEProgramOfWorksV1:"+table.Name){name=table.Name+" "+suffix++;sheet=FindEstimateSheet(name);}if(sheet==null)sheet=NewOutputSheet(name);sheet.UsedRange.ClearContents();var values=new object[table.Rows.GetLength(0)+1,4];for(int c=0;c<4;c++)values[0,c]=table.Headers[c];for(int r=0;r<table.Rows.GetLength(0);r++)for(int c=0;c<4;c++)values[r+1,c]=table.Rows[r,c];sheet.Range["A1:D"+values.GetLength(0)].Value2=values;sheet.Range["AA1"].Value2="DTCEProgramOfWorksV1:"+table.Name;sheet.Range["A1:D1"].Font.Bold=true;sheet.Range["C:D"].ColumnWidth=70;sheet.Range["A1:D"+values.GetLength(0)].WrapText=true;sheet.Range["A1:D"+values.GetLength(0)].Rows.AutoFit();QuantitySavePending=true;lastIssueText=stamp;}finally{try{if(active!=null)active.Activate();}catch{}app.ScreenUpdating=updates;app.EnableEvents=events;}}
}
}
